package com.chatsystem.user.controller.social;import com.chatsystem.shared.model.UserAccount;import com.chatsystem.shared.service.*;import com.chatsystem.user.controller.chat.NewConversationDialogController;import javafx.fxml.FXML;import javafx.scene.control.*;
public final class AddFriendDialogController{private final SocialService social;private final AdminService directory;@FXML private ComboBox<UserAccount> targetChoice;@FXML private Label feedbackLabel;public AddFriendDialogController(SocialService s,AdminService d){social=s;directory=d;}@FXML private void initialize(){targetChoice.setItems(directory.getUsers());targetChoice.setConverter(NewConversationDialogController.names());}@FXML private void submit(){var target=targetChoice.getValue();if(target==null){feedbackLabel.setText("Choose an account");return;}var r=social.sendRequest(target.getId());feedbackLabel.setText(r.isSuccess()?"Friend request sent":r.errors().get(0).message());}@FXML private void cancel(){targetChoice.getScene().getWindow().hide();}}
